import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        choices = []
        for name in names:
            versions = [v for v in rows_by_version[name]
                        if v not in blocked.get(name, [])
                        and (name not in pins or v == pins[name])]
            choices.append([-1] + versions)

        order = sorted(names, reverse=(name_order == "descending"))
        best_vector = None
        best_install = None
        maximize = preference == "maximum"

        for values in product(*choices):
            selected = dict(zip(names, values))
            valid = True
            for name, (low, high) in roots.items():
                version = selected[name]
                if version == -1 or not low <= version <= high:
                    valid = False
                    break
            if not valid:
                continue

            edges = {}
            for name, version in selected.items():
                if version == -1:
                    continue
                row = rows_by_version[name][version]
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = selected[other]
                    if (other_version == -1 or
                            not dep["min"] <= other_version <= dep["max"]):
                        valid = False
                        break
                    deps.append(other)
                edges[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            closure = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in closure:
                    continue
                closure.add(name)
                pending.extend(edges.get(name, []))
            if closure != {n for n, v in selected.items() if v != -1}:
                continue

            state = {}

            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                state[name] = 2
                return True

            if not all(visit(name) for name in closure):
                continue

            vector = tuple(selected[name] for name in order)
            if (best_vector is None or
                    (vector > best_vector if maximize else vector < best_vector)):
                best_vector = vector
                best_install = {n: selected[n] for n in names
                                if selected[n] != -1}

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "floor":
            return numerator // 10000
        return (2 * numerator + 10000) // 20000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = sorted(job["id"] for job in subset)
        id_set = set(ids)
        if not mandatory.issubset(id_set):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start_mask = bits.get(source, 0)
    initial = (source, start_mask, 0)
    distances = {initial: data["start"]}
    queue = [(data["start"], source, start_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                spent == data["coupons"]):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], spent)]
            if spent < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, spent + 1))
            for duration, next_spent in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_spent)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask,
                                           next_spent))
    return {"arrival": None}


